#!/usr/bin/env python3
"""Independent fixed-X6 audit checks; no author or repository mathematical imports."""
from collections import defaultdict
from fractions import Fraction
from itertools import product
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent

def deletion(state, axis):
    out = defaultdict(int)
    for cell, count in state.items():
        out[cell[:axis] + cell[axis+1:]] += count
    return {key: value for key, value in out.items() if value}

def axis_readout(state, axis):
    out = defaultdict(int)
    for cell, count in state.items():
        out[cell[axis]] += count
    return dict(sorted(out.items()))

def update(state):
    out = defaultdict(int)
    for cell, count in state.items():
        target = (1,0,0,0,0,0) if cell == (0,0,0,0,0,0) else cell
        out[target] += count
    return dict(out)

def rank_exact(rows):
    pivots = {}
    for initial in rows:
        row = {j: Fraction(v) for j,v in enumerate(initial) if v}
        while row:
            pivot = min(row)
            if pivot not in pivots:
                divisor = row[pivot]
                pivots[pivot] = {j:v/divisor for j,v in row.items()}
                break
            scale = row[pivot]
            for j,v in pivots[pivot].items():
                row[j] = row.get(j, 0) - scale*v
                if not row[j]:
                    del row[j]
    return len(pivots)

def check_box(shape):
    cells = list(product(*(range(n) for n in shape)))
    rows = []
    for i in range(6):
        keys = sorted(set(cell[:i]+cell[i+1:] for cell in cells))
        for key in keys:
            rows.append([int(cell[:i]+cell[i+1:]==key) for cell in cells])
    rank = rank_exact(rows)
    basis = []
    for index in product(*(range(n-1) for n in shape)):
        vector = {}
        for bits in product((0,1), repeat=6):
            cell = tuple(index[i]+bits[i] for i in range(6))
            vector[cell] = (-1)**sum(bits)
        assert all(not deletion(vector,i) for i in range(6))
        basis.append([vector.get(cell,0) for cell in cells])
    basis_rank = rank_exact(basis)
    expected = 1
    for n in shape:
        expected *= n-1
    assert basis_rank == expected == len(cells)-rank
    return {"shape":shape,"cells":len(cells),"deletion_rank_Q":rank,
            "kernel_rank_Q":len(cells)-rank,"basis_rank_Q":basis_rank,
            "integer_basis_claim":"proved algebraically in audit; Q rank alone does not certify integral saturation"}

def main():
    frozen = ROOT / "phase-a-freeze.input.md"
    digest = hashlib.sha256(frozen.read_bytes()).hexdigest()
    assert digest == "88ae2291744448beb32a1151c8e9f5f0a254dcf0f11b109c881241126d0b3b5d"
    cells = list(product((0,1), repeat=6))
    f = {cell:1 for cell in cells if sum(cell)%2==0}
    g = {cell:1 for cell in cells if sum(cell)%2==1}
    assert len(f)==len(g)==32
    assert all(deletion(f,i)==deletion(g,i) for i in range(6))
    fu,gu = update(f),update(g)
    assert axis_readout(fu,0)=={0:15,1:17}
    assert axis_readout(gu,0)=={0:16,1:16}
    assert deletion(fu,0)==deletion(gu,0)
    assert all(deletion(fu,i)!=deletion(gu,i) for i in range(1,6))
    report = {"frozen_sha256":digest,"parity":{"positive_mass":32,"negative_mass":32,
        "support":64,"all_six_deletion_marginals_equal":True},
        "relocation":{"f_axis1_after":axis_readout(fu,0),"g_axis1_after":axis_readout(gu,0),
        "deleting_axis1_stays_equal":True,"deleting_any_other_axis_differs":True},
        "boxes":[check_box(s) for s in [(1,2,2,2,2,2),(2,2,2,2,2,2),(3,2,2,2,2,2),(3,3,2,2,2,2)]],
        "scope":"Finite exact checks supplement, do not establish, the general proofs.",
        "imports_author_code":False}
    (ROOT/"independent-check-results.json").write_text(json.dumps(report,indent=2)+"\n")
    print(json.dumps(report,indent=2))

if __name__ == "__main__":
    main()

